values ('tech-cybersecurity', '00000000-0000-4000-8000-000000000001', 'サイバーセキュリティの進化', 'Morrisワームからランサムウェアの産業化まで。攻撃と脅威・防御と技術・法と国家の3層を重ね、個人の悪戯だった攻撃が国家戦と社会インフラの問題へ拡大する過程を追う。', 'technology', 'ja', 'public', 's_tech-cybersecurity', 1986, 2024, 'tech-cybersecurity')
on conflict (slug) do update set title = excluded.title, description = excluded.description, category = excluded.category,
  start_year = excluded.start_year, end_year = excluded.end_year, updated_at = now();
delete from public.layers where timeline_id = (select id from public.timelines where slug = 'tech-cybersecurity');
delete from public.events where timeline_id = (select id from public.timelines where slug = 'tech-cybersecurity');
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'tech-cybersecurity'), '攻撃と脅威', 'pink', 0);
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'tech-cybersecurity'), '防御と技術', 'blue', 1);
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'tech-cybersecurity'), '法と国家', 'teal', 2);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'tech-cybersecurity'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'tech-cybersecurity') and name = '法と国家'),
          '1986-10-01', null, 'month', 'point', '米国でコンピュータ詐欺濫用法(CFAA)成立', '権限のないコンピュータへのアクセスを連邦犯罪と定めるコンピュータ詐欺濫用法が米国で成立した。映画「ウォー・ゲーム」が象徴したハッカーへの社会不安を背景に、サイバー犯罪を裁く初の本格的な法枠組みとなった。

まだ大きな実害が出る前に法が先行した珍しい例で、2年後のMorrisワーム(攻撃と脅威レイヤー)はこの法律による最初の重要判例を生む。「不正アクセス」の定義の広さは、今日まで論争が続いている。', null,
          'verified', null, 'user', 0) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Computer Fraud and Abuse Act', 'https://en.wikipedia.org/wiki/Computer_Fraud_and_Abuse_Act')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'tech-cybersecurity'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'tech-cybersecurity') and name = '攻撃と脅威'),
          '1988-11-02', null, 'day', 'point', 'Morrisワーム、インターネットを初めて麻痺させる', 'コーネル大学の大学院生ロバート・モリスが放った自己増殖プログラムが、当時のインターネット接続機の約1割にあたる推定6000台を停止させた。悪意より実験目的だったとされるが、被害は全米に及んだ。

**ネットワークそのものが攻撃の媒介になる**ことを初めて示した事件であり、対応組織CERT/CCの設立(防御と技術レイヤー)を直接生んだ。モリスはCFAAによる最初期の有罪判決を受け、法と技術の追いかけ合いが始まった。', null,
          'verified', null, 'user', 1) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Morris worm', 'https://en.wikipedia.org/wiki/Morris_worm')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'tech-cybersecurity'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'tech-cybersecurity') and name = '防御と技術'),
          '1991-06-01', null, 'month', 'point', 'PGP公開、強い暗号が市民の手に', 'フィル・ジマーマンが公開鍵暗号を誰でも使えるメール暗号化ソフトPGPを無償公開した。軍事技術と扱われてきた強い暗号が、初めて一般市民の手に渡った。

米政府は暗号の輸出規制違反としてジマーマンを捜査し、「暗号戦争」と呼ばれる政府と技術者の対立(法と国家レイヤー)が始まった。捜査は後に打ち切られ、この対立の構図は2013年のスノーデン事件を経て現在の暗号化論争まで続いている。', null,
          'verified', null, 'user', 2) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Pretty Good Privacy', 'https://en.wikipedia.org/wiki/Pretty_Good_Privacy')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'tech-cybersecurity'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'tech-cybersecurity') and name = '攻撃と脅威'),
          '2000-05-04', null, 'day', 'point', 'ILOVEYOUワームが世界数千万台に感染', '「ILOVEYOU」という件名のメールで広がるワームがフィリピンから放たれ、数時間で世界の数千万台に感染した。被害総額は数十億ドルから100億ドル超と推計され、各国の政府機関や企業がメールシステムを停止した。

人の心理を突いて開封させる手口は、後のフィッシングの原型といえる。作成者は当時のフィリピンに処罰法がなく訴追されず、各国にサイバー犯罪立法(法と国家レイヤー)を急がせる契機となった。', null,
          'unverified', '感染台数・被害総額はいずれもセキュリティ企業等の推計で、集計方法により大きな幅がある。', 'user', 3) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: ILOVEYOU', 'https://en.wikipedia.org/wiki/ILOVEYOU')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'tech-cybersecurity'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'tech-cybersecurity') and name = '攻撃と脅威'),
          '2007-04-27', '2007-05-18', 'day', 'period', 'エストニアに大規模サイバー攻撃', 'ソ連兵士像の移設をめぐるロシアとの対立を背景に、エストニアの政府・銀行・報道機関のサイトが約3週間にわたり大規模なDDoS攻撃を受けた。電子政府先進国の行政サービスが断続的に停止した。

**国家全体が攻撃対象になった**初の事例と位置づけられ、翌年NATOはタリンにサイバー防衛協力センターを設立(法と国家レイヤー)した。国家間攻撃の交戦規定を論じる「タリン・マニュアル」もここから生まれた。', null,
          'disputed', 'ロシア政府の関与は状況証拠から広く疑われているが、公式には立証されておらず帰属が確定していない。', 'user', 4) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 2007 cyberattacks on Estonia', 'https://en.wikipedia.org/wiki/2007_cyberattacks_on_Estonia')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'tech-cybersecurity'),
