          '2010-06-01', null, 'month', 'point', 'Stuxnet発見、物理設備を破壊したマルウェア', 'イランのウラン濃縮施設の遠心分離機を狙ったマルウェアStuxnetが発見された。制御システムに潜り込み、正常値を装いながら遠心分離機を破壊するという、前例のない精密さを持っていた。

**コードが物理世界を破壊した**初の事例とされ、報道では米国とイスラエルの共同作戦と伝えられている。サイバー攻撃が外交・軍事の手段であることが公然の事実となり、各国の攻撃能力開発(法と国家レイヤー)が加速した。', null,
          'disputed', '米国・イスラエルの関与は複数の報道と研究者の分析に基づくもので、両政府とも公式には認めていない。', 'user', 5) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Stuxnet', 'https://en.wikipedia.org/wiki/Stuxnet')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'tech-cybersecurity'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'tech-cybersecurity') and name = '法と国家'),
          '2013-06-01', null, 'month', 'point', 'スノーデンがNSAの大規模監視を告発', '元NSA契約職員エドワード・スノーデンが、米政府による通信の大規模収集プログラムの内部文書を暴露した。同盟国の首脳や一般市民の通信までが収集対象だったことが明らかになった。

敵は犯罪者だけでなく**自国の政府でもあり得る**という認識が広がり、通信の常時暗号化(防御と技術レイヤー)が業界標準へと一気に進んだ。プライバシーと安全保障のバランスをめぐる議論の前提を変えた告発である。', null,
          'verified', null, 'user', 6) returning id)
