          '2015-06-01', null, 'day', 'point', '日本年金機構から125万件の年金情報が流出', '日本年金機構が標的型メール攻撃を受け、氏名・基礎年金番号など約125万件の個人情報が流出したと発表した。職員が添付ファイルを開いたことを起点に、内部ネットワークへ侵入された。

日本の公的機関を狙った標的型攻撃の深刻さを国民に知らしめた事案であり、成立直後のサイバーセキュリティ基本法(法と国家レイヤー)の下で初の大規模検証が行われた。マイナンバー制度開始前夜という時期も、行政のセキュリティ議論を加速させた。', null,
          'verified', null, 'user', 8) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('日本年金機構: 不正アクセスによる情報流出事案について (2015年6月)', null)) as v(title, url);
